		/**
		 * Tests getting all SubrogationRecoverys.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of SubrogationRecoverys:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all SubrogationRecovery : " );        
			List<SubrogationRecovery> collection  = null;

			try {
				// call the static get method on the SubrogationRecoveryService
				collection = SubrogationRecoveryService.getSubrogationRecoveryInstance().getAllSubrogationRecovery();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					SubrogationRecovery entity = null;            
					Iterator<SubrogationRecovery> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getSubrogationRecoveryId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

